import { db } from "../lib/db";
import { decryptSecret } from "../lib/crypto-box";
import * as fs from "node:fs";

const SCRATCH = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad";

async function main() {
  const s = await db.server.findUnique({
    where: { id: "cmsecmdps0001hlp27ai6mr7c" },
    select: { id: true, name: true, ipAddress: true, sshPort: true, rootPasswordEnc: true, status: true },
  });
  if (!s) { console.log("NO SERVER"); await db.$disconnect(); return; }
  if (s.ipAddress !== "51.79.226.215") {
    console.error("IP ASSERT FAILED: got " + s.ipAddress + " expected 51.79.226.215");
    await db.$disconnect(); process.exit(1);
  }
  const pw = decryptSecret(s.rootPasswordEnc);
  fs.writeFileSync(SCRATCH + "/kaymo-pw", pw ?? "", { mode: 0o600 });
  console.log(JSON.stringify({ id: s.id, name: s.name, ip: s.ipAddress, sshPort: s.sshPort, status: s.status, pwOk: !!pw, pwLen: pw?.length ?? 0 }, null, 2));

  // Find the Kaymo board + contact form card
  const boards = await db.board.findMany({
    where: { name: { contains: "Kaymo", mode: "insensitive" } },
    include: { columns: { orderBy: { position: "asc" } }, cards: { include: { column: true } } },
  });
  for (const b of boards) {
    console.log("BOARD", b.id, b.name);
    console.log("  COLUMNS:", b.columns.map(c => `${c.name}(${c.id})`).join(", "));
    for (const c of b.cards) {
      if (/contact/i.test(c.title)) {
        console.log("  CARD", c.id, "title=", JSON.stringify(c.title), "column=", c.column.name);
      }
    }
  }
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

