/* ---------- Contact form: graceful mailto fallback ---------- */
var form = $("#inquiryForm");
if (form) {
  var KAYLEE_EMAIL = "kbamvideo@gmail.com";
  var note = $(".form__note", form);

  var confirm = function (name) {
    if (!note) return;
    note.innerHTML =
      "Your email app should be opening now with your message ready to send. " +
      "If nothing opened, email me directly at " +
      "<a href=\"mailto:" + KAYLEE_EMAIL + "\" data-cursor>" + KAYLEE_EMAIL + "</a> " +
      "<button type=\"button\" class=\"form__copy\" data-cursor>Copy email</button>";
    note.classList.add("form__note--sent");
    var copyBtn = $(".form__copy", note);
    if (copyBtn) copyBtn.addEventListener("click", function () {
      var done = function () { copyBtn.textContent = "Copied ✓"; };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(KAYLEE_EMAIL).then(done, done);
      } else {
        var t = document.createElement("textarea");
        t.value = KAYLEE_EMAIL; document.body.appendChild(t); t.select();
        try { document.execCommand("copy"); } catch (err) {}
        document.body.removeChild(t); done();
      }
    });
  };

  form.addEventListener("submit", function (e) {
    var action = form.getAttribute("action") || "";
    var configured = action.indexOf("formspree.io/f/") > -1 && action.indexOf("your-form-id") === -1;
    if (configured) return; // real endpoint set — let it POST
    e.preventDefault();
    var get = function (n) { var el = form.elements[n]; return el ? el.value.trim() : ""; };
    var name = get("name"), email = get("email");
    if (!name || !email) {
      var first = !name ? form.elements["name"] : form.elements["email"];
      if (first) first.focus();
      return;
    }
    var body =
      "Name: " + name + "\n" +
      "Partner: " + get("partner") + "\n" +
      "Wedding date: " + get("date") + "\n" +
      "Venue / location: " + get("venue") + "\n" +
      "Email: " + email + "\n\n" +
      get("message");
    var href = "mailto:" + KAYLEE_EMAIL + "?subject=" +
      encodeURIComponent("Wedding film inquiry — " + name) +
      "&body=" + encodeURIComponent(body);
    window.location.href = href;
    confirm(name);
  });
}

