/* ---------- Contact form: FormSubmit (AJAX) with graceful fallback ---------- */
var form = $("#inquiryForm");
if (form) {
  var KAYLEE_EMAIL = "kbamvideo@gmail.com";
  var AJAX_ENDPOINT = "https://formsubmit.co/ajax/" + KAYLEE_EMAIL;
  var note = $(".form__note", form);

  var setNote = function (html, cls) {
    if (!note) return;
    note.innerHTML = html;
    note.classList.remove("form__note--sent", "form__note--error");
    if (cls) note.classList.add(cls);
  };

  var showSuccess = function (name) {
    setNote(
      "Thank you" + (name ? ", " + name : "") + " — your inquiry is on its way. " +
      "I'll be in touch soon at the email you shared.",
      "form__note--sent"
    );
  };

  var showError = function () {
    setNote(
      "Something went wrong sending your inquiry. Please email me directly at " +
      "<a href=\"mailto:" + KAYLEE_EMAIL + "\" data-cursor>" + KAYLEE_EMAIL + "</a>.",
      "form__note--error"
    );
  };

  // Confirm inline if we came back from the no-JS FormSubmit redirect (?sent=1).
  try {
    if (/[?&]sent=1(&|$)/.test(window.location.search)) {
      showSuccess("");
      form.reset();
      if (window.history && window.history.replaceState) {
        window.history.replaceState({}, document.title,
          window.location.pathname + window.location.hash);
      }
    }
  } catch (err) {}

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var get = function (n) { var el = form.elements[n]; return el ? String(el.value).trim() : ""; };
    var name = get("name"), email = get("email");
    if (!name || !email) {
      var first = !name ? form.elements["name"] : form.elements["email"];
      if (first) first.focus();
      return;
    }
    var btn = $("button[type=submit]", form);
    var btnHTML = btn ? btn.innerHTML : "";
    if (btn) { btn.disabled = true; btn.innerHTML = "Sending…"; }
    setNote("Sending your inquiry…");

    fetch(AJAX_ENDPOINT, {
      method: "POST",
      headers: { "Accept": "application/json" },
      body: new FormData(form)
    })
    .then(function (r) { return r.ok; })
    .then(function (ok) {
      if (ok) { form.reset(); showSuccess(name); }
      else { showError(); }
    })
    .catch(function () { showError(); })
    .then(function () {
      if (btn) { btn.disabled = false; btn.innerHTML = btnHTML; }
    });
  });
}

