const CARD_ID = "cmsevk6jj000ihlq5g7a9qugc";
const DONE_COL = "cmsetvsv3000chl24p9ehwaar"; // Done

async function main() {
  const done = await db.boardColumn.findUnique({ where: { id: DONE_COL } });
  if (!done) throw new Error("Done column not found");
  const maxPos = await db.card.aggregate({
    where: { columnId: DONE_COL }, _max: { position: true },
  });
  const nextPos = (maxPos._max.position ?? -1) + 1;

  const card = await db.card.update({
    where: { id: CARD_ID },
    data: { columnId: DONE_COL, position: nextPos },
    select: { id: true, title: true, columnId: true },
  });

  const body =
    "✅ Contact form is now wired to **FormSubmit** and LIVE.\n\n" +
    "**What changed**\n" +
    "- Form action → `https://formsubmit.co/kbamvideo@gmail.com` (no signup / no API key). The old Formspree placeholder + mailto popup are gone.\n" +
    "- JS intercepts submit and POSTs via AJAX to `https://formsubmit.co/ajax/kbamvideo@gmail.com`, showing an on-page success state (no redirect). If JS is off, the native POST redirects to `?sent=1#contact` and still confirms inline.\n" +
    "- Hidden fields: `_subject`=\"New inquiry — Kaymo Film Co\", `_template`=table, `_captcha`=false, `_next`=`https://kaymo.revsports.ca/?sent=1#contact`, plus a `_honey` honeypot.\n" +
    "- All original fields kept (name, partner, date, venue, email, message). Graceful error message falls back to the mailto address on failure.\n\n" +
    "**Verified live**: `https://kaymo.revsports.ca/` returns 200; the FormSubmit action + hidden fields are present in the served HTML; the AJAX endpoint is in main.js.\n\n" +
    "⚠️ **ONE-TIME ACTIVATION REQUIRED (Kaylee must do this once):** FormSubmit sends a confirmation email to **kbamvideo@gmail.com** on the FIRST submission. Send ONE test submission through the live form, then open that email and click **Activate** / confirm the address. Until that link is clicked, submissions will NOT be forwarded. After activating once, every future inquiry emails the studio automatically.";

  await db.cardComment.create({
    data: { cardId: CARD_ID, authorName: "claude", body },
  });

  console.log(JSON.stringify({ moved: card, addedComment: true }, null, 2));
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

